// One line of text, or a refusal -- not a row of whatever arrived.
const raw = typeof $json.chatInput === 'string' ? $json.chatInput : '';
const title = raw.replace(/\s+/g, ' ').trim();
if (!title) {
  throw new Error('the task text (chatInput) is empty');
}
if (title.length > 300) {
  throw new Error('the task text is longer than 300 characters');
}
return [{ json: { title } }];
